        String batchUrl = base + "/api/collections/" + collection + "/documents/batch";
        String json = toJson(new KbUploadDocumentInfoResponse(
                kbId,
                kb.getName(),
                batchUrl,
                "POST",
                "multipart/form-data",
                "files (必填, 支持多文件批量上传，最多 20 个)",
                "单次最多 20 个文件",
                "无需认证"
        ));
        return successResult(json);
