public McpSchema.CallToolResult handleKbDocumentStatus(Long kbId, Integer docId) {
    logger.info("MCP kb document status: kbId={}, docId={}", kbId, docId);
    try {
        KbResponse kb = knowledgeBaseService.getKnowledgeBase(kbId);
        String collection = kb.getRagCollection();

        if (docId != null && docId > 0) {
            Map<String, Object> doc = ragApiClient.getDocumentStatusById(collection, docId);
            return successResult(toJson(doc));
        } else {
            List<Map<String, Object>> docs = ragApiClient.getDocumentStatus(collection);
            KbDocumentStatusResponse response = new KbDocumentStatusResponse(kbId, kb.getName(), docs);
            return successResult(toJson(response));
        }
    } catch (Exception e) {
        logger.error("Error querying kb document status", e);
        return errorResult("查询文档状态失败: " + e.getMessage());
    }
}

private String incrementVersion(String currentVersion) {
    if (currentVersion == null || currentVersion.isBlank()) {
        return "1.0.1";
    }
    int lastDot = currentVersion.lastIndexOf('.');
    if (lastDot < 0) {
        return currentVersion + ".1";
    }
    String prefix = currentVersion.substring(0, lastDot + 1);
    String lastSegment = currentVersion.substring(lastDot + 1);

    // 提取最后一段开头的数字部分
    int digitEnd = 0;
    while (digitEnd < lastSegment.length() && Character.isDigit(lastSegment.charAt(digitEnd))) {
        digitEnd++;
    }
    if (digitEnd == 0) {
        // 最后一段不以数字开头（如 "alpha"）
        return currentVersion + ".1";
    }
    String numPart = lastSegment.substring(0, digitEnd);
    String suffixPart = lastSegment.substring(digitEnd);
    int num = Integer.parseInt(numPart);
    return prefix + (num + 1) + suffixPart;
}

private McpSchema.CallToolResult successResult(String json) {
    return McpSchema.CallToolResult.builder(List.of(new McpSchema.TextContent(json)))
            .isError(false)
            .build();
}

private McpSchema.CallToolResult errorResult(String message) {
    return McpSchema.CallToolResult.builder(List.of(new McpSchema.TextContent(
                    toJson(new ErrorResponse(message)))))
            .isError(true)
            .build();
}

private String toJson(Object obj) {
    try {
        return objectMapper.writeValueAsString(obj);
    } catch (Exception e) {
        logger.error("Failed to serialize to JSON", e);
        return "{}";
    }
}

