@Component
public class McpResourceHandler {

    private static final Logger logger = LoggerFactory.getLogger(McpResourceHandler.class);

    private final McpSearchService searchService;

    public McpResourceHandler(McpSearchService searchService) {
        this.searchService = searchService;
    }

    /**
     * 返回工具列表
     */
    public List<Map<String, Object>> listTools() {
        List<ToolSearchResult> tools = searchService.searchTools(null, null, 50);
        List<Map<String, Object>> result = new ArrayList<>();

        for (ToolSearchResult tool : tools) {
            result.add(Map.of(
                    "name", "h3_coding_hub_tool_" + tool.getId(),
                    "description", tool.getName() + " - " + tool.getDescription(),
                    "inputSchema", Map.of(
                            "type", "object",
                            "properties", Map.of(
                                    "toolId", Map.of("type", "integer", "description", "Tool ID")
                            )
                    )
            ));
        }

        return result;
    }

    /**
     * 工具搜索
     */
    public List<ToolSearchResult> searchTools(String query, String category, Integer limit) {
        return searchService.searchTools(query, category, limit);
    }

    /**
     * 获取工具详情
     */
    public String getToolContent(Long toolId) {
        Tool tool = searchService.getToolById(toolId);
        if (tool == null) {
            throw new IllegalArgumentException("Tool not found: " + toolId);
        }
        return tool.getContent() != null ? tool.getContent() : "";
    }
}

public List<Map<String, Object>> listTools() {
    List<ToolSearchResult> tools = searchService.searchTools(null, null, 50);
    List<Map<String, Object>> result = new ArrayList<>();

    for (ToolSearchResult tool : tools) {
        result.add(Map.of(
                "name", "h3_coding_hub_tool_" + tool.getId(),
                "description", tool.getName() + " - " + tool.getDescription(),
                "inputSchema", Map.of(
                        "type", "object",
                        "properties", Map.of(
                                "toolId", Map.of("type", "integer", "description", "Tool ID")
                        )
                )
        ));
    }

    return result;
}

public List<ToolSearchResult> searchTools(String query, String category, Integer limit) {
    return searchService.searchTools(query, category, limit);
}

public String getToolContent(Long toolId) {
    Tool tool = searchService.getToolById(toolId);
    if (tool == null) {
        throw new IllegalArgumentException("Tool not found: " + toolId);
    }
    return tool.getContent() != null ? tool.getContent() : "";
}

@Configuration
public class McpSdkServerConfig {

    private static final Logger logger = LoggerFactory.getLogger(McpSdkServerConfig.class);

    private final ObjectMapper objectMapper;

    public McpSdkServerConfig(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    // ── 公共 Bean ──────────────────────────────────────────────────

    @Bean
    public McpJsonMapper mcpJsonMapper(ObjectMapper objectMapper) {
        return new JacksonMcpJsonMapper(objectMapper);
    }

    // ── Streamable HTTP 传输 ──────────────────────────────────────

    @Bean
    public HttpServletStreamableServerTransportProvider streamableTransportProvider(McpJsonMapper mcpJsonMapper) {
        return HttpServletStreamableServerTransportProvider.builder()
                .jsonMapper(mcpJsonMapper)
                .mcpEndpoint("/mcp")
                .build();
    }

    @Bean
    public ServletRegistrationBean<HttpServletStreamableServerTransportProvider> streamableServletBean(
            HttpServletStreamableServerTransportProvider transportProvider) {
        return new ServletRegistrationBean<>(transportProvider, "/mcp", "/mcp/*");
    }

    // ── SSE 传输（兼容旧客户端）──────────────────────────────────

    @Bean
    public HttpServletSseServerTransportProvider sseTransportProvider(McpJsonMapper mcpJsonMapper) {
        return HttpServletSseServerTransportProvider.builder()
                .jsonMapper(mcpJsonMapper)
                .messageEndpoint("/sse/message")
                .sseEndpoint("/sse")
                .build();
    }

    @Bean
    public ServletRegistrationBean<HttpServletSseServerTransportProvider> sseServletBean(
            HttpServletSseServerTransportProvider transportProvider) {
        return new ServletRegistrationBean<>(transportProvider, "/sse", "/sse/message");
    }

    // ── McpServer 实例 ────────────────────────────────────────────

    /**
     * Streamable HTTP McpServer（主实例，注入到其他组件时使用此实例）。
     */
    @Primary
    @Bean(destroyMethod = "close")
    public McpSyncServer streamableMcpServer(HttpServletStreamableServerTransportProvider transportProvider,
                                             IaihubToolHandler toolHandler) {
        McpSyncServer server = McpServer.sync(transportProvider)
                .serverInfo("H3CodingHub-MCP-Server", "2.0.0")
                .capabilities(McpSchema.ServerCapabilities.builder()
                        .tools(true)
                        .logging()
                        .build())
                .build();

        registerAllTools(server, toolHandler);
        logger.info("MCP Server (streamable-http, /mcp) initialized with 18 tools");
        return server;
    }

    /**
     * SSE McpServer（兼容旧客户端）。
     */
    @Bean(destroyMethod = "close")
    public McpSyncServer sseMcpServer(HttpServletSseServerTransportProvider transportProvider,
                                      IaihubToolHandler toolHandler) {
        McpSyncServer server = McpServer.sync(transportProvider)
                .serverInfo("H3CodingHub-MCP-Server", "2.0.0")
                .capabilities(McpSchema.ServerCapabilities.builder()
                        .tools(true)
                        .logging()
                        .build())
                .build();

        registerAllTools(server, toolHandler);
        logger.info("MCP Server (SSE, /sse) initialized with 18 tools");
        return server;
    }

