                .pinned(tool.getPinned() != null ? tool.getPinned() : false)
                .viewCount(tool.getViewCount() != null ? tool.getViewCount() : 0)
                .likeCount(tool.getLikeCount() != null ? tool.getLikeCount() : 0)
