_mapErrorToCode(error: any): string {
      if (!error.response) return 'UNKNOWN';
      const status = error.response.status;
      switch (status) {
        case 401: return 'AUTH';
        case 403: return 'FORBIDDEN';
        case 404: return 'NOT_FOUND';
        default: return 'UNKNOWN';
      }
    }

