def list_collections() -> list[dict]:
    """List all collections with document counts and descriptions.

    Returns:
        [{"name": str, "doc_count": int, "description": str}, ...]
    """
    store = get_store()
    names = store.list_collections()
    result = []
    for name in names:
        try:
            docs = store.list_documents(collection=name)
            config = store.get_collection_config(name)
            result.append({
                "name": name,
                "doc_count": len(docs),
                "description": config.get("description", ""),
            })
        except Exception as e:
            logger.warning(f"Skipping broken collection '{name}': {e}")
            result.append({
                "name": name,
                "doc_count": 0,
                "description": f"(error: {e})",
            })
    return result

