def delete_collection(
    collection: str = "default",
) -> str:
    """Delete an entire knowledge base collection and all its documents.

    WARNING: This permanently removes the collection including all
    indexed documents, vectors, and configuration. This cannot be undone.

    Args:
        collection: Name of the collection to delete (default: "default").
    """
    result = service.delete_collection(collection)

    if result.get("status") == "ok":
        return (
            f"Collection '{collection}' has been deleted along with "
            f"all its documents and vectors."
        )
    else:
        return f"Error: {result.get('error', 'Unknown error')}"

rag/server.py::document_status.source_code:
def document_status(
    collection: str = "default",
    doc_id: int = 0,
) -> str:
    """Query document processing status in the knowledge base.

    Documents go through states: UPLOADING → CONVERTING → CHUNKING →
    EMBEDDING → READY (success) or FAILED (error).

    Args:
        collection: Collection name to query (default: "default").
        doc_id: Specific document ID to query. 0 = list all documents
            in the collection with their status.
    """
    from api.app import get_db

    try:
        db = get_db()
    except RuntimeError:
        return "Error: Database not initialized. Document status tracking requires the REST API to be enabled (use --mode sse or --mode streamable-http without --no-api)."

    if doc_id > 0:
        doc = db.get_document_by_id(doc_id)
        if doc is None:
            return f"Document {doc_id} not found."
        if doc["collection"] != collection:
            return f"Document {doc_id} not in collection '{collection}'."
        status = doc["status"]
        line = (
            f"[{doc['id']}] {doc['filename']} — {status}"
            f" ({doc['chunk_count']} chunks"
        )
        if doc.get("error_message"):
            line += f", error: {doc['error_message']}"
        line += ")"
        return f"Document status in '{collection}':\n  {line}"

    docs = db.get_documents(collection)
    if not docs:
        return f"No documents tracked in collection '{collection}'."

    lines = [f"Documents in '{collection}' ({len(docs)} total):\n"]
    for doc in docs:
        status = doc["status"]
        line = f"  [{doc['id']}] {doc['filename']} — {status}"
        if status == "READY":
            line += f" ({doc['chunk_count']} chunks)"
        elif status == "FAILED" and doc.get("error_message"):
            line += f" (error: {doc['error_message']})"
        lines.append(line)

    return "\n".join(lines)

rag/server.py::main.source_code:
def main():
    """Entry point for the MCP server."""
    mode = _args.mode

    if mode == "stdio":
        mcp.run(transport="stdio")

    elif mode in ("sse", "streamable-http"):
        if _args.api:
            # Combined mode: REST API + MCP on the same port
            import uvicorn

            app = _create_combined_app()

            if mode == "sse":
                logger.info(
                    f"Starting wandering-rag-mcp in SSE mode: "
                    f"http://{_args.host}:{_args.port}/sse"
                )
                logger.info(
                    f"REST API available at: "
                    f"http://{_args.host}:{_args.port}/api/"
                )
            else:
                logger.info(
                    f"Starting wandering-rag-mcp in Streamable HTTP mode: "
                    f"http://{_args.host}:{_args.port}/mcp"
                )
                logger.info(
                    f"REST API available at: "
                    f"http://{_args.host}:{_args.port}/api/"
                )

            uvicorn.run(app, host=_args.host, port=_args.port)
        else:
            # MCP-only mode (no REST API)
            if mode == "sse":
                logger.info(
                    f"Starting wandering-rag-mcp in SSE mode: "
                    f"http://{_args.host}:{_args.port}/sse"
                )
            else:
                logger.info(
                    f"Starting wandering-rag-mcp in Streamable HTTP mode: "
                    f"http://{_args.host}:{_args.port}/mcp"
                )
            mcp.run(transport=mode)

